/**
 * Data-layer entry point. Repositories import `{ getDb }` and the table
 * objects from here so the concrete client module stays swappable.
 */
export { getDb, useInMemoryDb } from "./client";
export type { Db, DbSchema } from "./client";
export * from "./schema";
import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

const NOTIFICATION_KINDS = [
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
] as const;

export const notifications = sqliteTable(
  "notifications",
  {
    id: idColumn(),
    ...tenantColumns,
    recipientId: text("recipient_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    href: text("href").notNull(),
    actorId: text("actor_id"),
    readAt: text("read_at"),
    /** JSON array of `NotificationChannel`. */
    channels: text("channels").notNull().default('["in_app"]'),
    ...timestampColumns,
  },
  (table) => [
    index("notifications_org_recipient_idx").on(table.orgId, table.recipientId),
    index("notifications_org_read_idx").on(table.orgId, table.readAt),
  ],
);

export const notificationPreferences = sqliteTable(
  "notification_preferences",
  {
    ...tenantColumns,
    userId: text("user_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    inApp: integer("in_app", { mode: "boolean" }).notNull().default(true),
    email: integer("email", { mode: "boolean" }).notNull().default(true),
    digestOnly: integer("digest_only", { mode: "boolean" })
      .notNull()
      .default(false),
  },
  (table) => [
    uniqueIndex("notification_preferences_pk").on(
      table.orgId,
      table.userId,
      table.kind,
    ),
  ],
);

export type NotificationRow = typeof notifications.$inferSelect;
export type NewNotificationRow = typeof notifications.$inferInsert;
export type NotificationPreferenceRow =
  typeof notificationPreferences.$inferSelect;
"use client";

/**
 * Per-kind channel matrix; the digest column is hidden unless `digest_email`
 * is on.
 *
 * Must call (do not reimplement): isEnabled
 */
import { Switch } from "@/components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
import { useFormAction } from "@/hooks/use-form-action";
import { isEnabled } from "@/lib/feature-flags";
import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
import type { ActionResult } from "@/types/api";
import type { OrgId, UserId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type {
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";
import type { ReactElement } from "react";

export type NotificationPreferencesFormProps = {
  orgId: OrgId;
  userId: UserId;
  preferences: readonly NotificationPreference[];
  flags: FeatureFlagSnapshot;
  onSubmit: (
    input: UpdateNotificationPreferenceInput,
  ) => Promise<ActionResult<NotificationPreference>>;
};

const KIND_LABELS: Readonly<Record<NotificationKind, string>> = {
  issue_assigned: "Issue assigned to me",
  issue_status_changed: "Issue status changed",
  issue_due_soon: "Issue due soon",
  issue_overdue: "Issue overdue",
  comment_created: "New comment",
  comment_mention: "I was mentioned",
  member_invited: "Member invited",
  member_joined: "Member joined",
  project_archived: "Project archived",
  plan_limit_reached: "Plan limit reached",
  digest_ready: "Daily digest ready",
};

export function NotificationPreferencesForm(
  props: NotificationPreferencesFormProps,
): ReactElement | null {
  const { orgId, userId, preferences, flags, onSubmit } = props;
  const { submit, pending } = useFormAction(onSubmit);

  const digestOn =
    flags.digest_email === true ||
    isEnabled("digest_email", ANONYMOUS_FLAG_CONTEXT);

  function update(
    preference: NotificationPreference,
    patch: Partial<
      Pick<NotificationPreference, "inApp" | "email" | "digestOnly">
    >,
  ): void {
    void submit({
      orgId,
      userId,
      kind: preference.kind,
      inApp: patch.inApp ?? preference.inApp,
      email: patch.email ?? preference.email,
      digestOnly: patch.digestOnly ?? preference.digestOnly,
    });
  }

  return (
    <Table caption="Notification preferences">
      <TableHead>
        <TableRow>
          <TableHeaderCell>Event</TableHeaderCell>
          <TableHeaderCell>In app</TableHeaderCell>
          <TableHeaderCell>Email</TableHeaderCell>
          {digestOn ? <TableHeaderCell>Digest only</TableHeaderCell> : null}
        </TableRow>
      </TableHead>

      <TableBody>
        {preferences.map((preference) => (
          <TableRow key={preference.kind}>
            <TableCell>{KIND_LABELS[preference.kind]}</TableCell>

            <TableCell className="w-24">
              <Switch
                name={`${preference.kind}-in-app`}
                checked={preference.inApp}
                disabled={pending}
                onChange={(checked) => update(preference, { inApp: checked })}
              />
            </TableCell>

            <TableCell className="w-24">
              <Switch
                name={`${preference.kind}-email`}
                checked={preference.email}
                disabled={pending}
                onChange={(checked) => update(preference, { email: checked })}
              />
            </TableCell>

            {digestOn ? (
              <TableCell className="w-28">
                <Switch
                  name={`${preference.kind}-digest`}
                  checked={preference.digestOnly}
                  // Batching only makes sense when email is on at all.
                  disabled={pending || !preference.email}
                  onChange={(checked) =>
                    update(preference, { digestOnly: checked })
                  }
                />
              </TableCell>
            ) : null}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}
/**
 * Soft-delete filtering.
 *
 * Archived rows stay in the table and disappear from every default read. The
 * cases below pin both halves of that: an archived issue is invisible unless
 * `includeArchived` is set, and archiving a project cascades to its issues.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let live: Issue;
let archived: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("softdelete");

  live = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Still open" }),
  );

  const doomed = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Archived away" }),
  );

  archived = await issueService.archiveIssue(
    tenant.actors.member,
    tenant.org.id,
    doomed.id,
  );
});

afterAll(() => {
  cleanup();
});

describe("archived issues", () => {
  it("marks the row rather than deleting it", async () => {
    expect(archived.archivedAt).not.toBeNull();

    const stillThere = await issueRepo.findIssueById(
      tenant.org.id,
      archived.id,
    );
    expect(stillThere?.id).toBe(archived.id);
  });

  it("is excluded from the default listing", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((issue) => issue.id)).toEqual([live.id]);
    expect(page.total).toBe(1);
  });

  it("reappears when the caller opts in", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
      includeArchived: true,
    });

    expect(page.total).toBe(2);
    expect(page.items.map((issue) => issue.id).sort()).toEqual(
      [live.id, archived.id].sort(),
    );
  });

  it("is excluded from the per-project count the quota reads", async () => {
    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id),
    ).resolves.toBe(1);

    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).resolves.toBe(2);
  });

  it("is excluded from the board columns", async () => {
    const columns = await issueRepo.listBoardColumns(
      tenant.org.id,
      tenant.project.id,
    );
    const ids = columns.flatMap((column) => column.issues.map((i) => i.id));

    expect(ids).toEqual([live.id]);
  });

  it("keeps its issue number reserved", async () => {
    await expect(
      issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
    ).resolves.toBe(3);
  });

  it("refuses to be archived twice", async () => {
    await expect(
      issueService.archiveIssue(
        tenant.actors.member,
        tenant.org.id,
        archived.id,
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("archiving a project", () => {
  it("cascades to the project's live issues", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Scratch",
      slug: "scratch",
      key: "SCR",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await issueService.createIssue(
