/**
 * Primitive identifier and envelope types shared by every Taskflow domain type.
 *
 * Every entity in Taskflow uses opaque branded string ids so that an `IssueId`
 * can never be silently passed where a `ProjectId` is expected. Ids are ULID
 * strings at runtime; the brand exists only at the type level.
 */

declare const brand: unique symbol;

/** Attaches a compile-time-only tag to a primitive type. */
export type Branded<T, B extends string> = T & { readonly [brand]: B };

export type UserId = Branded<string, "UserId">;
export type OrgId = Branded<string, "OrgId">;
export type ProjectId = Branded<string, "ProjectId">;
export type IssueId = Branded<string, "IssueId">;
export type CommentId = Branded<string, "CommentId">;
export type MemberId = Branded<string, "MemberId">;
export type NotificationId = Branded<string, "NotificationId">;
export type ActivityId = Branded<string, "ActivityId">;
export type InvitationId = Branded<string, "InvitationId">;
export type LabelId = Branded<string, "LabelId">;
export type AttachmentId = Branded<string, "AttachmentId">;
export type SubscriptionId = Branded<string, "SubscriptionId">;
export type SessionId = Branded<string, "SessionId">;
export type WebhookId = Branded<string, "WebhookId">;

/** Union of every branded id used in the app, for generic id helpers. */
export type AnyId =
  | UserId
  | OrgId
  | ProjectId
  | IssueId
  | CommentId
  | MemberId
  | NotificationId
  | ActivityId
  | InvitationId
  | LabelId
  | AttachmentId
  | SubscriptionId
  | SessionId
  | WebhookId;

/** ISO-8601 timestamp string as stored in SQLite text columns. */
export type IsoTimestamp = Branded<string, "IsoTimestamp">;

/** Rows carrying the standard created/updated bookkeeping columns. */
export interface Timestamps {
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

/**
 * Soft-delete marker. `archivedAt === null` means the row is live. Repositories
 * must filter on this via the helpers in `src/lib/soft-delete.ts` rather than
 * writing the predicate by hand.
 */
export interface SoftDeletable {
  readonly archivedAt: IsoTimestamp | null;
}

/** Rows that belong to exactly one tenant. Enforced by `src/lib/tenant.ts`. */
export interface TenantScoped {
  readonly orgId: OrgId;
}

export type SortDirection = "asc" | "desc";

export interface SortSpec<TField extends string = string> {
  readonly field: TField;
  readonly direction: SortDirection;
}

/** Cursor pagination request shared by every repository `list*` method. */
export interface PageRequest {
  readonly limit: number;
  readonly cursor?: string | null;
}

/** Cursor pagination response shared by every repository `list*` method. */
export interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
  readonly total: number;
}

/** Options accepted by every soft-delete-aware repository read. */
export interface ArchiveScope {
  readonly includeArchived?: boolean;
}

export function makePage<T>(
  items: readonly T[],
  nextCursor: string | null,
  total: number,
): Page<T> {
  return { items, nextCursor, total };
}

export function toIsoTimestamp(value: Date | string): IsoTimestamp {
  const date = typeof value === "string" ? new Date(value) : value;
  return date.toISOString() as IsoTimestamp;
}

/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
  NotFoundError,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  SetIssueParentInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueRollup, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

async function requireParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId), "Issue", parentId,
  );
  if (parent.projectId !== projectId) throw new NotFoundError("Issue", parentId);
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/** Validate both the destination and the deepest node that travels with it. */
async function assertParentPlacement(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
  issueId?: IssueId,
): Promise<void> {
  let parent = parentId === null ? null : await requireParent(orgId, projectId, parentId);
  const errorId = issueId ?? parentId!;
  const descendants = issueId === undefined ? [] : await issueRepo.listDescendantIssues(
    orgId, issueId, { includeArchived: true },
  );
  if (parent && (parent.id === issueId || descendants.some(issue => issue.id === parent!.id))) {
    throw new IssueHierarchyError(errorId, "cycle");
  }

  let destinationDepth = 0;
  const ancestors = new Set<IssueId>();
  while (parent !== null) {
    if (ancestors.has(parent.id) || parent.id === issueId) {
      throw new IssueHierarchyError(errorId, "cycle");
    }
    ancestors.add(parent.id);
    destinationDepth += 1;
    parent = parent.parentId === null ? null : await requireParent(orgId, projectId, parent.parentId);
  }

  const children = new Map<IssueId, IssueId[]>();
  for (const descendant of descendants) {
    if (descendant.parentId !== null) {
      const siblings = children.get(descendant.parentId) ?? [];
      siblings.push(descendant.id);
      children.set(descendant.parentId, siblings);
    }
  }
  const queue = issueId === undefined ? [] : [{ id: issueId, depth: 0 }];
  const visited = new Set<IssueId>();
  let height = 0;
  for (let index = 0; index < queue.length; index += 1) {
    const node = queue[index];
    if (visited.has(node.id)) throw new IssueHierarchyError(errorId, "cycle");
    visited.add(node.id);
    height = Math.max(height, node.depth);
    for (const id of children.get(node.id) ?? []) {
      queue.push({ id, depth: node.depth + 1 });
    }
  }
  if (destinationDepth + height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(errorId, "too_deep");
  }
}

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  await assertParentPlacement(input.orgId, input.projectId, input.parentId);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

