  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const { issues: archived, completedParents } = await issueRepo.archiveIssueSubtree(orgId, issueId);
  for (const descendant of archived) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: descendant.id,
      projectId: descendant.projectId,
    });
  }
  for (const parent of completedParents) {
    await announceSubIssuesCompleted(actor, parent);
  }

  return requireFound(archived.find(row => row.id === issueId), "Issue", issueId);
