function completedParent(orgId: OrgId, child: Issue): Issue | null {
  if (child.parentId === null) return null;
  const row = getDb().select().from(issues).where(and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.id, child.parentId),
    eq(issues.projectId, child.projectId),
    isNull(issues.archivedAt),
    isNotNull(issues.assigneeId),
  )).get();
  if (!row || readIssueRollup(orgId, child.parentId).open !== 0) return null;
  return toIssue(row);
}

