/** Status transitions maintain `started_at` / `completed_at` bookkeeping. */
export async function setIssueStatus(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<Issue> {
  return writeIssueStatus(orgId, issueId, status);
}

function writeIssueStatus(orgId: OrgId, issueId: IssueId, status: IssueStatus): Issue {
  const stamp = toIsoTimestamp(new Date());
  const current = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  const row = getDb()
    .update(issues)
    .set({
      status,
      startedAt:
        status === "in_progress" && current.startedAt === null
          ? stamp
          : current.startedAt,
      completedAt: TERMINAL_STATUSES.includes(status) ? stamp : null,
      updatedAt: stamp,
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  return toIssue(row);
}

/** Capture completion at the write, so simultaneous sibling closings notify once. */
export async function setIssueStatusWithCompletion(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<{ before: Issue; after: Issue; completedParent: Issue | null }> {
  return getDb().transaction(() => {
    const row = getDb().select().from(issues).where(and(
      orgPredicate(issues.orgId, orgId), eq(issues.id, issueId),
    )).get();
    if (!row) throw new Error(`Issue ${issueId} not found`);
    const before = toIssue(row);
    const after = before.status === status ? before : writeIssueStatus(orgId, issueId, status);
    const closing = before.archivedAt === null &&
      !CLOSED_ISSUE_STATUSES.includes(before.status) && CLOSED_ISSUE_STATUSES.includes(status);
    return { before, after, completedParent: closing ? completedParent(orgId, before) : null };
  });
}

