/** One write archives the live subtree before any archive event is delivered. */
export async function archiveIssueSubtree(
  orgId: OrgId,
  issueId: IssueId,
): Promise<{ issues: readonly Issue[]; completedParents: readonly Issue[] }> {
  const result = getDb().transaction(() => {
    const predicate = and(
      orgPredicate(issues.orgId, orgId),
      inArray(issues.id, subtreeIds(orgId, issueId)),
      isNull(issues.archivedAt),
    );
    const before = getDb().select().from(issues).where(predicate).all();
    const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(predicate)
    .returning()
    .all();
    const parents = new Map<IssueId, Issue>();
    for (const child of before) {
      if (CLOSED_ISSUE_STATUSES.includes(child.status)) continue;
      const parent = completedParent(orgId, toIssue(child));
      if (parent !== null) parents.set(parent.id, parent);
    }
    return { rows, completedParents: [...parents.values()] };
  });
  const labels = await listLabelsForIssues(orgId, result.rows.map(row => row.id as IssueId));
  return {
    issues: result.rows.map(row => toIssue(row, (labels[row.id] ?? []).map(label => label.id))),
    completedParents: result.completedParents,
  };
}

export async function restoreIssue(
  orgId: OrgId,
