import type { Actor, Role } from "@/types/member";
import { ROLE_RANK } from "@/types/member";
import type {
  PermissionAction,
  PermissionDecision,
  PermissionResource,
} from "@/types/permission";

/**
 * The single authorization entry point for Taskflow.
 *
 * Every Server Action, service method, Route Handler and permission-sensitive
 * UI component funnels through `can()`. Nothing else may branch on
 * `actor.role` directly — if you find yourself writing `role === "admin"`,
 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
 *
 * Decision order:
 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
 *   2. platform staff bypass
 *   3. role matrix lookup
 *   4. ownership escalations (authors edit their own issues/comments)
 */

/** Minimum role required for each action, before ownership escalations. */
export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
  "org:read": "viewer",
  "org:update": "admin",
  "org:delete": "owner",
  "org:manage_billing": "owner",
  "org:manage_flags": "admin",
  "member:read": "viewer",
  "member:invite": "admin",
  "member:update_role": "admin",
  "member:remove": "admin",
  "project:create": "member",
  "project:read": "viewer",
  "project:update": "member",
  "project:archive": "admin",
  "project:delete": "owner",
  "issue:create": "member",
  "issue:read": "viewer",
  "issue:update": "member",
  "issue:assign": "member",
  "issue:archive": "member",
  "issue:delete": "admin",
  "comment:create": "member",
  "comment:read": "viewer",
  "comment:update": "member",
  "comment:delete": "admin",
  "activity:read": "member",
  "activity:export": "admin",
  "notification:read": "viewer",
  "notification:manage": "viewer",
  "webhook:manage": "admin",
};

/** Actions an actor may perform on their own content regardless of role rank. */
const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
  "issue:update": true,
  "issue:archive": true,
  "comment:update": true,
  "comment:delete": true,
  "notification:manage": true,
};

function isOwnedByActor(
  actor: Actor,
  resource: PermissionResource,
): boolean {
  switch (resource.kind) {
    case "issue":
      return (
        resource.authorId === actor.userId ||
        resource.assigneeId === actor.userId
      );
    case "comment":
      return resource.authorId === actor.userId;
    case "project":
      return resource.leadId === actor.userId;
    case "notification":
      return resource.recipientId === actor.userId;
    case "member":
      return resource.targetUserId === actor.userId;
    default:
      return false;
  }
}

/**
 * Answers "may this actor perform this action on this resource?".
 *
 * @param actor    the authenticated principal, always scoped to one org
 * @param action   a member of the closed `PermissionAction` vocabulary
 * @param resource the object being acted on, discriminated on `kind`
 */
export function can(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): boolean {
  return explain(actor, action, resource).allowed;
}

/** Same decision as `can()`, but reports why — used by the settings UI. */
export function explain(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): PermissionDecision {
  const base = { action, resourceKind: resource.kind } as const;

  if (actor.orgId !== resource.orgId) {
    return { ...base, allowed: false, reason: "denied_cross_tenant" };
  }

  if (actor.isPlatformStaff === true) {
    return { ...base, allowed: true, reason: "granted_by_staff" };
  }

  const required = ROLE_MATRIX[action];
  if (required === undefined) {
    return { ...base, allowed: false, reason: "denied_unknown_action" };
  }

  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
    return { ...base, allowed: true, reason: "granted_by_role" };
  }

  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
    return { ...base, allowed: true, reason: "granted_by_ownership" };
  }

  return { ...base, allowed: false, reason: "denied_by_role" };
}

/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
export class PermissionDeniedError extends Error {
  readonly code = "forbidden" as const;

  constructor(
    readonly action: PermissionAction,
    readonly decision: PermissionDecision,
  ) {
    super(`Permission denied: ${action} on ${decision.resourceKind}`);
    this.name = "PermissionDeniedError";
  }
}

/** Throwing variant of `can()` for service-layer guard clauses. */
export function assertCan(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): void {
  const decision = explain(actor, action, resource);
  if (!decision.allowed) {
    throw new PermissionDeniedError(action, decision);
  }
}

/** Bulk evaluation used by navigation and toolbar components. */
export function canAll(
  actor: Actor,
  actions: readonly PermissionAction[],
  resource: PermissionResource,
): boolean {
  return actions.every((action) => can(actor, action, resource));
}
/** `createIssueSchema` defaults, bounds and error paths. */
import { describe, expect, it } from "vitest";
import {
  archiveIssueSchema,
  assignIssueSchema,
  changeIssueStatusSchema,
  createIssueSchema,
  issueFilterSchema,
  moveIssueSchema,
  updateIssueSchema,
} from "@/schemas/issue";
import { ISSUE_PRIORITIES, ISSUE_STATUSES } from "@/types/issue";
import { ALICE, ORG_A } from "../helpers/factories";

const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP";
const ISSUE = "01HZZZSSSSSSSSSSSSSSSSSSSS";

function createInput(overrides: Record<string, unknown> = {}) {
  return { orgId: ORG_A, projectId: PROJECT, title: "Fix the link", ...overrides };
}

describe("schemas/issue", () => {
  it("applies every documented default", () => {
    expect(createIssueSchema.parse(createInput())).toMatchObject({
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  });

  it("accepts every status and priority in the domain", () => {
    for (const status of ISSUE_STATUSES) {
      expect(createIssueSchema.safeParse(createInput({ status })).success, status).toBe(
        true,
      );
    }
    for (const priority of ISSUE_PRIORITIES) {
      expect(
        createIssueSchema.safeParse(createInput({ priority })).success,
        priority,
      ).toBe(true);
    }
  });

  it("rejects a status outside the enum", () => {
    expect(createIssueSchema.safeParse(createInput({ status: "shipped" })).success).toBe(
      false,
    );
  });

  it("bounds the title at 3 and 200 characters, reporting the title path", () => {
    expect(createIssueSchema.safeParse(createInput({ title: "ab" })).success).toBe(false);
    expect(
      createIssueSchema.safeParse(createInput({ title: "a".repeat(201) })).success,
    ).toBe(false);

    const result = createIssueSchema.safeParse(createInput({ title: "ab" }));
    if (result.success) return;
    expect(result.error.issues[0]?.path).toEqual(["title"]);
    expect(result.error.issues[0]?.message).toBe("give the issue a title");
  });

  it("requires ULID ids and reports the offending path", () => {
    const result = createIssueSchema.safeParse(createInput({ projectId: "nope" }));
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.issues[0]?.path).toEqual(["projectId"]);
  });

  it("bounds the estimate to a whole number between 0 and 100", () => {
    expect(createIssueSchema.safeParse(createInput({ estimate: 8 })).success).toBe(true);
    expect(createIssueSchema.safeParse(createInput({ estimate: 1.5 })).success).toBe(
      false,
    );
    expect(createIssueSchema.safeParse(createInput({ estimate: 101 })).success).toBe(
      false,
    );
    expect(createIssueSchema.safeParse(createInput({ estimate: null })).success).toBe(
      true,
    );
  });

  it("caps the label list at 20", () => {
    const label = "01HZZZKKKKKKKKKKKKKKKKKKKK";
    expect(
      createIssueSchema.safeParse(createInput({ labelIds: Array(20).fill(label) }))
        .success,
    ).toBe(true);
    expect(
      createIssueSchema.safeParse(createInput({ labelIds: Array(21).fill(label) }))
        .success,
    ).toBe(false);
  });

  it("requires a real ISO datetime for dueAt", () => {
    expect(
      createIssueSchema.safeParse(createInput({ dueAt: "2026-03-15T12:00:00.000Z" }))
        .success,
    ).toBe(true);
    expect(createIssueSchema.safeParse(createInput({ dueAt: "2026-03-15" })).success).toBe(
      false,
    );
  });

  it("makes every updatable field optional on update", () => {
    expect(updateIssueSchema.parse({ orgId: ORG_A, issueId: ISSUE })).toEqual({
      orgId: ORG_A,
      issueId: ISSUE,
    });
  });

  it("still bounds fields that are present on update", () => {
    expect(
      updateIssueSchema.safeParse({ orgId: ORG_A, issueId: ISSUE, title: "ab" }).success,
    ).toBe(false);
  });

  it("requires a status on the status-change payload", () => {
    expect(
      changeIssueStatusSchema.safeParse({ orgId: ORG_A, issueId: ISSUE }).success,
    ).toBe(false);
    expect(
      changeIssueStatusSchema.parse({ orgId: ORG_A, issueId: ISSUE, status: "done" })
        .status,
    ).toBe("done");
  });

  it("allows unassignment with an explicit null", () => {
    expect(
      assignIssueSchema.parse({ orgId: ORG_A, issueId: ISSUE, assigneeId: null })
        .assigneeId,
    ).toBeNull();
    expect(
      assignIssueSchema.parse({ orgId: ORG_A, issueId: ISSUE, assigneeId: ALICE })
        .assigneeId,
    ).toBe(ALICE);
    expect(assignIssueSchema.safeParse({ orgId: ORG_A, issueId: ISSUE }).success).toBe(
      false,
    );
  });

  it("carries pagination and archive scope on the filter schema", () => {
    const parsed = issueFilterSchema.parse({ orgId: ORG_A });
    expect(parsed.limit).toBe(25);
    expect(parsed.includeArchived).toBeUndefined();

    expect(
      issueFilterSchema.parse({ orgId: ORG_A, limit: 50, includeArchived: true }),
    ).toMatchObject({ limit: 50, includeArchived: true });
    expect(issueFilterSchema.safeParse({ orgId: ORG_A, limit: 101 }).success).toBe(false);
  });

  it("requires a non-negative board index on move", () => {
    expect(
      moveIssueSchema.safeParse({
        orgId: ORG_A,
        issueId: ISSUE,
        toStatus: "todo",
        toIndex: -1,
      }).success,
    ).toBe(false);
    expect(
      moveIssueSchema.safeParse({
        orgId: ORG_A,
        issueId: ISSUE,
        toStatus: "todo",
        toIndex: 0,
      }).success,
    ).toBe(true);
  });

  it("needs only the org and issue to archive", () => {
    expect(archiveIssueSchema.parse({ orgId: ORG_A, issueId: ISSUE })).toEqual({
      orgId: ORG_A,
      issueId: ISSUE,
    });
  });
});
/**
 * Label rows and the issue↔label join table.
 */
import { and, asc, eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueLabels, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toLabel } from "./_mappers";
import type { CreateLabelInput, UpdateLabelInput } from "@/schemas/label";
import type { IssueId, LabelId, OrgId } from "@/types/common";
import type { IssueLabel } from "@/types/issue";

export async function listLabels(
  orgId: OrgId,
): Promise<readonly IssueLabel[]> {
  const rows = getDb()
    .select()
    .from(labels)
    .where(orgPredicate(labels.orgId, orgId))
    .orderBy(asc(labels.name))
    .all();
  return rows.map(toLabel);
}

export async function insertLabel(
  input: CreateLabelInput,
): Promise<IssueLabel> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(labels)
    .values({
      id: newId(),
      orgId: input.orgId,
      name: input.name,
      color: input.color,
      description: input.description,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toLabel(row);
}

export async function updateLabel(
  input: UpdateLabelInput,
): Promise<IssueLabel> {
  const row = getDb()
    .update(labels)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.color === undefined ? {} : { color: input.color }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(labels.orgId, input.orgId), eq(labels.id, input.labelId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Label ${input.labelId} not found`);
  return toLabel(row);
}

/** Labels are hard deleted; the join rows go with them. */
export async function deleteLabel(
  orgId: OrgId,
  labelId: LabelId,
): Promise<void> {
  const db = getDb();
  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, labelId),
      ),
    )
    .run();
  db.delete(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, labelId)))
    .run();
}

/** Replaces the whole label set of one issue in a single round trip. */
export async function setIssueLabels(
  orgId: OrgId,
  issueId: IssueId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const db = getDb();
  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.issueId, issueId),
      ),
    )
    .run();

  if (labelIds.length === 0) return;

  db.insert(issueLabels)
    .values(labelIds.map((labelId) => ({ orgId, issueId, labelId })))
    .run();
}

/** Batched lookup keyed by issue id, so list views avoid an N+1. */
export async function listLabelsForIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Readonly<Record<string, readonly IssueLabel[]>>> {
  if (issueIds.length === 0) return {};

  const rows = getDb()
    .select({ issueId: issueLabels.issueId, label: labels })
    .from(issueLabels)
    .innerJoin(labels, eq(labels.id, issueLabels.labelId))
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...issueIds]),
      ),
    )
    .all();

  const grouped: Record<string, IssueLabel[]> = {};
  for (const row of rows) {
    (grouped[row.issueId] ??= []).push(toLabel(row.label));
  }
  return grouped;
}
